 enum OperationKey ___A___ Key {

 ADD((val1, val2) -> val1 + val2),

 SUBTRACT((val1, val2) -> val1 - val2),

 MULTIPLY((val1, val2) -> val1 * val2),

 DIVIDE((val1, val2) -> val1 / val2),

 EQUAL(null),

