public class CourseManagement {

public static void main(String[] args) {

CourseManagement cm = new CourseManagement();

String c1 = cm.newCourse("Programming Language I", "C105");

String c2 = cm.newCourse("Programming Language II", "C205");

String c3 = cm.newCourse("Data Structures", "C215");

String s1 = cm.newStudent("Kamal Rahim", "17127", 15, 2.0);

String s2 = cm.newStudent("Tamara Iqbal", "16200", 24, 3.0);

String f1 = cm.newFaculty("Dr. Tasnim Khan", "F7980");

String f2 = cm.newFaculty("Dr. Zia Kabir", "F4589");

cm.assignCourse(f1, c1);

cm.assignCourse(f2, c2);

cm.assignCourse(f2, c3);

cm.takeCourse(s1, c1);

cm.takeCourse(s1, c2);

cm.takeCourse(s2, c1);

cm.takeCourse(s2, c2);

cm.submitGrade(f1, c1, s1, 2.0);

cm.submitGrade(f1, c1, s2, 3.0);

cm.submitGrade(f2, c2, s2, 2.0);

System.out.printf("Student: %s, CGPA: %3.2f%n",

s2, cm.cgpa(s2));

}

public Map<String, Student> students = new HashMap<>();

public Map<String, Faculty> faculties = new HashMap<>();

public Map<String, Course> courses = new HashMap<>();

public String newStudent(String name, String id,

int creditHours, double cgpa) {

students.put(id, new Student(name, id, creditHours, cgpa));

return id;

}

public String newFaculty(String name, String id) {

faculties.put(id, new Faculty(name, id));

return id;

}

public String newCourse(String title, String code) {

courses.put(code, new Course(title, code));

return code;

}

public boolean assignCourse(String fid, String code) {
 return ***G***;
 }

public boolean takeCourse(String sid, String code) {

return students.get(sid).addCourse(courses.get(code));

}

public boolean submitGrade(String fid, String code, String sid,

double grade) {

return faculties.get(fid).submitGrade(code, sid, grade);

}

public double cgpa(String sid) {

return students.get(sid).calculateCgpa();

}

}

