[Program 3]

 import java.util.Map;

 import java.util.HashMap;

 public class Student {

 private static final int MAX_COURSES = 6;

 private final String name;

 private final String id;

 private final int creditHours;

 private final double cgpa;
 private final Map< ___D___ > courses = new HashMap<>();

 Student(String name, String id, int creditHours, double cgpa) {

 this.name = name;

 this.id = id;

 this.creditHours = creditHours;

 this.cgpa = cgpa;

 }

 boolean addCourse(Course course) {
 if (courses.size() < MAX_COURSES && ___F___ ) {
 return courses.put(course.getCode(), course) == null;

 }

 return false;

 }

 double calculateCgpa() {

 double sum = creditHours * cgpa;

 double totalCreditHours;

 for (Course course : courses.values()) {

 sum += course.getGrade(id) * Course.CREDIT_HOUR;

 }

 totalCreditHours =

