),
(
  '2023-april',
  'A',
  33,
  'Q33. How many host addresses are there in the network 192.168.10.0/26?',
  '[{"type":"text","page":13,"bbox":[65.22,212.93,439.39,243.26],"text":"Q33.\nHow many host addresses are there in the network 192.168.10.0/26?"},{"type":"text","page":13,"bbox":[84.12,266.93,476.1,280.21],"text":"a) 30\nb) 62\nc) 126\nd) 254"}]'::jsonb,
