  '[{"label":"a","text":"skipLeadingZeros(strNum), strNum, strlen(strNum)"},{"label":"b","text":"skipLeadingZeros(strNum), strNum, strlen(strNum) + 1"},{"label":"c","text":"strNum, skipLeadingZeros(strNum), strlen(skipLeadingZeros(strNum))"},{"label":"d","text":"strNum, skipLeadingZeros(strNum), strlen(skipLeadingZeros(strNum)) + 1"}]'::jsonb,
  '[{"subquestion": 1, "blank": "A", "answer": "b"}, {"subquestion": 1, "blank": "B", "answer": "c"}, {"subquestion": 1, "blank": "C", "answer": "b"}, {"subquestion": 1, "blank": "D", "answer": "a"}, {"subquestion": 1, "blank": "E", "answer": "d"}, {"subquestion": 1, "blank": "F", "answer": "a"}, {"subquestion": 2, "blank": "G", "answer": "c"}, {"subquestion": 2, "blank": "H", "answer": "d"}]',
