INSERT INTO question_subtopics (question_id, subtopic_id, is_primary, confidence, classification_source)
SELECT q.id, s.id, true, v.confidence, 'llm'
FROM (VALUES
  (1, 'cryptography', 0.800),
  (2, 'operating-systems', 0.850),
  (3, 'databases', 0.950),
  (4, 'networking', 0.850),
  (5, 'algorithms', 0.650),
  (6, 'data-structures', 0.750),
  (7, 'algorithms', 0.600),
  (8, 'software-development', 0.650)
) AS v(question_number, slug, confidence)
JOIN questions q ON q.question_number = v.question_number
  AND q.exam_session = '2023-april' AND q.subject = 'B'
JOIN subtopics s ON s.slug = v.slug;

