),
(
  '2024-april',
  'A',
  24,
  'Q24. Which of the following is the broadcast address of the network 192.168.10.0/23?',
  '[{"type":"text","page":11,"bbox":[65.22,590.93,499.33,621.26],"text":"Q24.\nWhich of the following is the broadcast address of the network 192.168.10.0/23?"},{"type":"text","page":11,"bbox":[65.22,644.93,533.1,711.13],"text":"a) 192.168.10.0\nb) 192.168.10.255\nc) 192.168.10.511\nd) 192.168.11.255"},{"type":"code","page":11,"bbox":[65.22,794.63,317.4,807.97],"text":"– 11 –"}]'::jsonb,
  '[]'::jsonb,
  '[{"label":"a","text":"192.168.10.0"},{"label":"b","text":"192.168.10.255"},{"label":"c","text":"192.168.10.511"},{"label":"d","text":"192.168.11.255"}]'::jsonb,
  'd',
  '{"value":"d"}'::jsonb,
  'The broadcast address is 192.168.11.255. A /23 prefix leaves 9 host bits, so the network 192.168.10.0/23 covers 192.168.10.0 through 192.168.11.255, and the broadcast address is the last address, with all host bits set to 1. 192.168.10.255 is only the end of a /24 network, and 511 is not a valid octet value.',
  (SELECT id FROM subtopics WHERE slug = 'networking'),
  'medium',
  0.5,
  'questions.pdf',
  '(2024S, FE, Subject-A, Q24)',
  ARRAY[11]::int[],
  'native_text',
  '3.0',
  'Q24. Which of the following is the broadcast address of the network 192.168.10.0/23?

 a) 192.168.10.0 b) 192.168.10.255 c) 192.168.10.511 d) 192.168.11.255',
  '{"question_pdf":{"filename":"questions.pdf","storage_path":"2024-april/a/questions.pdf","pages":[11]},"answer_pdf":{"filename":"answers.pdf","storage_path":"2024-april/a/answers.pdf","pages":[1]}}'::jsonb,
  true
),
