 dice2 ← random_int(1, 6)
 sum ← dice1 + dice2
 if (sum = 7 or sum = 11)

wins_sum ← wins_sum + 1
 elseif (sum = 2 or sum = 3 or sum = 12)
 lose_sum ← lose_sum + 1
 else
