f\n  endfor\n  idf ← log(numDocs ÷ (1 + termCount)) /* Division is performed\n                                             in data type real */\n  return idf"},{"type":"answer_table","columns":["A","B"],"rows":[{"label":"a","values":{"A":"corpus[j] = term","B":"isContainsTerm = false"}},{"label":"b","values":{"A":"corpus[j] = term","B":"isContainsTerm = true"}},{"label":"c","values":{"A":"corpus[j] ≠ term","B":"isContainsTerm = false"}},{"label":"d","values":{"A":"corpus[j] ≠ term","B":"isContainsTerm = true"}},{"label":"e","values":{"A":"words[j] = term","B":"isContainsTerm = false"}},{"label":"f","values":{"A":"words[j] = term","B":"isContainsTerm = true"}},{"label":"g","values":{"A":"words[j] ≠ term","B":"isContainsTerm = false"}},{"label":"h","values":{"A":"words[j] ≠ term","B":"isContainsTerm = true"}}]}]'::jsonb,
  '[]'::jsonb,
  '[{"label":"a","text":"corpus[j] = term isContainsTerm = false","values":{"A":"corpus[j] = term","B":"isContainsTerm = false"}},{"label":"b","text":"corpus[j] = term isContainsTerm = true","values":{"A":"corpus[j] = term","B":"isContainsTerm = true"}},{"label":"c","text":"corpus[j] ≠ term isContainsTerm = false","values":{"A":"corpus[j] ≠ term","B":"isContainsTerm = false"}},{"label":"d","text":"corpus[j] ≠ term isContainsTerm = true","values":{"A":"corpus[j] ≠ term","B":"isContainsTerm = true"}},{"label":"e","text":"words[j] = term isContainsTerm = false","values":{"A":"words[j] = term","B":"isContainsTerm = false"}},{"label":"f","text":"words[j] = term isContainsTerm = true","values":{"A":"words[j] = term","B":"isContainsTerm = true"}},{"label":"g","text":"words[j] ≠ term isContainsTerm = false","values":{"A":"words[j] ≠ term","B":"isContainsTerm = false"}},{"label":"h","text":"words[j] ≠ term isContainsTerm = true","values":{"A":"words[j] ≠ term","B":"isContainsTerm = true"}}]'::jsonb,
